#include <algorithm>
#include <iostream>
#include <vector>
#include <map>
#include <random>
#include <stdexcept>
using namespace std;
void need(bool x,const char*s){if(!x)throw runtime_error(s);}
vector<vector<long long>> endpoints(const vector<int>&a){int n=a.size(),M=1<<n;vector<vector<long long>>d(M,vector<long long>(n));for(int v=0;v<n;v++)d[1<<v][v]=1;for(int S=1;S<M;S++)for(int u=0;u<n;u++)for(int Z=a[u]&~S;Z;Z&=Z-1){int b=Z&-Z;d[S|b][__builtin_ctz((unsigned)b)]+=d[S][u];}return d;}
long long cycles(const vector<int>&a){int n=a.size();if(n<3)return 0;int M=1<<n;vector<vector<long long>>d(M,vector<long long>(n));d[1][0]=1;for(int S=1;S<M;S++)for(int u=0;u<n;u++)for(int Z=a[u]&~S;Z;Z&=Z-1){int b=Z&-Z;d[S|b][__builtin_ctz((unsigned)b)]+=d[S][u];}long long z=0;for(int v=0;v<n;v++)if(a[v]&1)z+=d.back()[v];return z;}
long long H(const vector<int>&a){if(a.empty())return 1;auto d=endpoints(a);long long h=0;for(auto v:d.back())h+=v;return h;}
vector<int> build(const vector<int>&a,int r,int m){int t=a.size();vector<int>b(2*t+m);for(int i=0;i<t;i++)for(int j=0;j<t;j++){if(a[i]>>j&1){b[m+i]|=1<<(m+j);b[m+t+j]|=1<<(m+t+i);}if(i==r&&j==r)b[m+i]|=1<<(m+t+j);else b[m+t+j]|=1<<(m+i);}for(int u=0;u<m;u++){for(int v=u+1;v<m;v++)b[u]|=1<<v;for(int i=0;i<t;i++){b[u]|=1<<(m+i);b[m+t+i]|=1<<u;}}return b;}
long long marked(const vector<int>&a,int u,int v){int n=a.size(),M=1<<n;vector<vector<long long>>d(M,vector<long long>(2*n));for(int x=0;x<n;x++)d[1<<x][x]=1;for(int S=1;S<M;S++)for(int i=0;i<n;i++)for(int flag=0;flag<2;flag++)if(d[S][flag*n+i])for(int Z=a[i]&~S;Z;Z&=Z-1){int b=Z&-Z,j=__builtin_ctz((unsigned)b),f=flag||(i==u&&j==v);d[S|b][f*n+j]+=d[S][flag*n+i];}long long z=0;for(int i=0;i<n;i++)z+=d.back()[n+i];return z;}
long long inputs=0,clones=0,flips=0;long long maxdef=0;
void check(const vector<int>&a){int n=a.size(),M=1<<n;auto end=endpoints(a);vector<int>rev(n);for(int i=0;i<n;i++)rev[i]=((M-1)^(1<<i)^a[i]);auto start=endpoints(rev);vector<long long>hs(M);hs[0]=1;for(int S=1;S<M;S++)for(auto v:end[S])hs[S]+=v;long long h=hs.back();for(int r=0;r<n;r++){long long q=0,d=0,e=start.back()[r];for(int S=1;S<M;S++){long long w=end[S][r]*hs[(M-1)^S];q+=w;d+=(__builtin_popcount((unsigned)S)%2?-1:1)*w;}need(d==-e,"endpoint reciprocity");auto b=build(a,r,0);long long zero=H(b),gain=marked(b,r,n+r);need(zero==h*h+q*q-e*e,"zero-clone identity");need(cycles(b)==(n==1?0:end.back()[r]*end.back()[r]),"zero cycle square");need(gain==q*q && zero-gain==h*h-e*e,"single edge flip partition");need(q>=e&&(q-e)%2==0,"endpoint parity and inequality");need((q==e)==(rev[r]==0),"equality iff source");need(zero>=h*h&&zero%4==1,"even boundary lower and mod4");maxdef=max(maxdef,e*e);inputs++;flips++;
 if(n<=4)for(int m:{1,2}){need(H(build(a,r,m))==h*h+q*q*(1LL<<m),"positive clone boundary contrast");need(cycles(build(a,r,m))==end.back()[r]*end.back()[r],"positive cycle square");clones++;}
}}
int main(){for(int n=1;n<=5;n++){int k=n*(n-1)/2;for(int code=0;code<(1<<k);code++){vector<int>a(n);int z=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,z++){int u=(code>>z&1)?i:j,v=i+j-u;a[u]|=1<<v;}check(a);}}
mt19937 rng(1971155);for(int z=0;z<32;z++){vector<int>a(6);for(int i=0;i<6;i++)for(int j=i+1;j<6;j++){bool f=rng()&1;a[f?i:j]|=1<<(f?j:i);}check(a);}vector<int>tri={2,4,1};auto b=build(tri,0,0);need(H(b)==17,"triangle boundary witness");cout<<"PASS rooted_sides "<<inputs<<" literal_edge_flip_partitions "<<flips<<" positive_clone_controls "<<clones<<" maximum_square_deficit "<<maxdef<<"\n";for(int k=1;k<=6;k++){int t=k+2;vector<int>a(t);for(int i=0;i<t;i++)for(int j=i+1;j<t;j++)a[i]|=1<<j;a[0]^=1<<(t-1);a.back()|=1;auto g=build(a,0,0);long long expected=2*((1LL<<k)+1)*((1LL<<k)+1)-1;need(H(g)==expected&&cycles(g)==1,"quadratic family count");for(int i=0;i<2*t;i++)for(int j=0;j<2*t;j++)need((g[i]>>j&1)==(g[(j+t)%(2*t)]>>((i+t)%(2*t))&1),"physical anti involution");cout<<"FAMILY "<<k<<" "<<expected<<" C 1";if(k==5){cout<<" rows";for(int v:g)cout<<" "<<v;}cout<<"\n";}for(int p:{7,23,311}){for(int d=2;d*d<=p;d++)need(p%d!=0,"prime quotient");}need(8449==7*17*71,"divisibility hostile");cout<<"C3_boundary_rows";for(int x:b)cout<<" "<<x;cout<<" H 17\n";}
